function composeDesc(r){
  const def=String(r.definizione||'').trim();
  if(r.tipo==='USM'){
    const parts=[cap(def)||'Struttura muraria'];
    if(r.tecnica)parts[0]+=` in ${joinIt(tk(r.tecnica))}`;
    const lat=tk(r.lat_materiali),lit=tk(r.lit_materiali),alt=tk(r.materialiAltro);
    if(lat.length)parts.push(`laterizi: ${joinIt(lat)}${tk(r.lat_lavorazione).length?' '+joinIt(tk(r.lat_lavorazione)):''}${tk(r.lat_posa).length?', posti a '+joinIt(tk(r.lat_posa)):''}`);
    if(lit.length)parts.push(`elementi litici: ${joinIt(lit)}${tk(r.lit_lavorazione).length?' '+joinIt(tk(r.lit_lavorazione)):''}${tk(r.lit_posa).length?', in '+joinIt(tk(r.lit_posa)):''}`);
    if(alt.length)parts.push(`altri materiali: ${joinIt(alt)}`);
    const comp=tk(r.leg_componenti);
    if(/secco/i.test(r.leg_tipo||''))parts.push('messa in opera a secco');
    else if(r.leg_tipo||comp.length){let l=`legante: ${r.leg_tipo||'malta'}`;if(comp.length)l+=` di ${joinIt(comp)}`;if(r.leg_colore)l+=` di colore ${r.leg_colore}`;if(r.leg_consistenza)l+=`, ${r.leg_consistenza}`;parts.push(l)}
    if(tk(r.leg_finitura).length)parts.push(`giunti: ${joinIt(tk(r.leg_finitura))}`);
    if(r.finitureOpera)parts.push(r.finitureOpera);
    if(r.orientamento)parts.push(`orientamento ${r.orientamento}`);
    return parts.length===1&&!def&&!r.tecnica?'':parts.join('; ')+'.';
  }
  const cut=/taglio|interfaccia/i.test(def)||(/buca|fossa/i.test(def)&&(r.forma||r.pareti||r.fondo));
  if(cut){
    let s=cap(def)||'Taglio';
    if(r.forma)s+=` di forma ${r.forma}`;
    const pf=[];if(r.pareti)pf.push(`pareti ${r.pareti}`);if(r.fondo)pf.push(`fondo ${r.fondo}`);
    if(pf.length)s+=(r.forma?', ':' con ')+joinIt(pf);
    if(r.orientamento)s+=` con orientamento ${r.orientamento}`;
    return s+'.';
  }
  const geo=tk(r.geologici),mat=geo.filter(g=>MATRIX[g.toLowerCase()]),incl=geo.filter(g=>!MATRIX[g.toLowerCase()]);
  let s=cap(def)||'Strato';
  if(mat.length){const seen=new Set();const adj=mat.map(g=>MATRIX[g.toLowerCase()]).filter(a=>!seen.has(a)&&seen.add(a));
    s+=` con matrice a tessitura ${adj.map((a,i)=>a+(i===adj.length-1?'a':'o')).join('-')}`}
  if(r.colore&&r.consistenza)s+=` di colore ${r.colore} e consistenza ${r.consistenza}`;
  else if(r.colore)s+=` di colore ${r.colore}`;
  else if(r.consistenza)s+=` di consistenza ${r.consistenza}`;
  if(incl.length)s+=`, con inclusi di ${joinIt(incl)}`;
  const cont=[...tk(r.organici),...tk(r.artificiali),...tk(r.elementiDatanti)].filter(x=>!/^nessun/i.test(x));
  if(cont.length)s+=`, contenente ${joinIt(cont)}`;
  if(!def&&s==='Strato')return'';
  return s+'.';
}
