/* Cicli e contraddizioni nella sequenza stratigrafica.
   Uguale a / si lega a = stesso momento (nodi uniti); copre, taglia, riempie, si appoggia = posteriore; i rapporti inversi = anteriore. */
function findCycles(recs,relOf=(r,k)=>r.rel?.[k]||[]){
  const nums=new Set(recs.map(r=>r.numero));const par=new Map([...nums].map(n=>[n,n]));
  const f=x=>{while(par.get(x)!==x)x=par.get(x);return x};
  const groups=()=>{const g=new Map();nums.forEach(n=>{const k=f(n);if(!g.has(k))g.set(k,[]);g.get(k).push(n)});return g};
  recs.forEach(r=>['uguale','silega'].forEach(k=>relOf(r,k).forEach(n=>{if(nums.has(n)){const a=f(r.numero),b=f(n);if(a!==b)par.set(a,b)}})));
  const G=groups(),lab=k=>(G.get(k)||[k]).slice().sort(numSort).join('='),out=[],seen=new Set();
  const edges=new Map();const add=(a,b,why)=>{a=f(a);b=f(b);
    if(a===b){const t=`${why[0]} e ${why[1]} risultano contemporanee (uguale a / si lega a) ma anche in sequenza fra loro`;if(!seen.has(t)){seen.add(t);out.push({nums:[...why],t})}return}
    if(!edges.has(a))edges.set(a,new Set());edges.get(a).add(b)};
  recs.forEach(r=>{POST.forEach(k=>relOf(r,k).forEach(n=>{if(nums.has(n))add(r.numero,n,[r.numero,n])}));
                   ANTE.forEach(k=>relOf(r,k).forEach(n=>{if(nums.has(n))add(n,r.numero,[n,r.numero])}))});
  const col=new Map();
  const dfs=(u,stack)=>{col.set(u,1);stack.push(u);
    for(const v of edges.get(u)||[]){if(col.get(v)===1){const cyc=stack.slice(stack.indexOf(v)).concat(v);const t='Sequenza ciclica: '+cyc.map(lab).join(' → ');
      if(!seen.has(t)){seen.add(t);out.push({nums:[...new Set(cyc.flatMap(x=>G.get(x)||[x]))],t:t+' (una US non può essere insieme anteriore e posteriore a un’altra)'})}}
      else if(!col.get(v))dfs(v,stack)}
    stack.pop();col.set(u,2)};
  [...edges.keys()].sort(numSort).forEach(u=>{if(!col.get(u))dfs(u,[])});
  return out;
}
/* Scomposizione di una descrizione libera senza rete: rapporti con espressioni regolari, caratteri cercando le voci degli elenchi */
const REL_PAT=[['copertoda','copert[oa] da'],['tagliatoda','tagliat[oa] da'],['riempitoda','riempit[oa] da'],['gliappoggia','gli si appoggia(?:no)?'],
  ['siappoggia','si appoggia(?: a)?'],['silega','si lega(?: a| con)?'],['uguale','(?:è )?ugual[ei](?: a)?'],['copre','copre'],['taglia','taglia'],['riempie','riempie']];
const ADJ2COMP={sabbios:'sabbia',limos:'limo',argillos:'argilla',ghiaios:'ghiaia',ciottolos:'ciottoli'};
function localExtract(text,tipo,lists){
  const out={rel:{}};let rest=' '+text+' ';
  const numRe='(?:usm?\\s*)?(\\d+[a-z]?(?:\\s*(?:,|\\+|e|ed)\\s*(?:usm?\\s*)?\\d+[a-z]?)*)';
  REL_PAT.forEach(([k,pat])=>{const re=new RegExp('(?:^|[\\s,;.\\-–(])('+pat+')\\s+'+numRe,'gi');
    rest=rest.replace(re,(m,_,nums)=>{const arr=nums.split(/\s*(?:,|\+|\be\b|\bed\b)\s*/i).map(x=>x.replace(/^usm?\s*/i,'').trim().toUpperCase()).filter(Boolean);
      out.rel[k]=[...new Set([...(out.rel[k]||[]),...arr])];return ' '})});
  const desc=rest.replace(/\s*[-–,;]\s*(?=[-–,;.]|$)/g,'').replace(/\s{2,}/g,' ').replace(/[\s,;\-–]+\.?\s*$/,'').trim();
  out.descrizione=desc?(desc.endsWith('.')?desc:desc+'.'):'';
  const n=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const T=n(text),stem=w=>w.length>4?w.slice(0,-1):w;
  const has=v=>{const words=n(v).split(/\s+/).map(w=>w.replace(/[^a-z0-9]/g,'')).filter(Boolean);if(!words.length)return-1;
    const re=new RegExp('\\b'+words.map(w=>stem(w)+'[a-z]?').join('\\s+')+'\\b');const m=re.exec(T);return m?m.index:-1};
  const pick=(k,multi)=>{const list=(lists[k]||[]).slice().sort((a,b)=>b.length-a.length);const found=[];const used=[];
    list.forEach(v=>{const i=has(v);if(i<0)return;const e=i+n(v).length;if(used.some(([a,b])=>i<b&&e>a))return;used.push([i,e]);found.push([i,v])});
    found.sort((a,b)=>a[0]-b[0]);if(!found.length)return;out[k]=multi?found.map(f=>f[1]).join(', '):found[0][1]};
  ['colore','consistenza','definizione','conservazione','forma','pareti','fondo'].forEach(k=>pick(k,false));
  ['organici','artificiali','elementiDatanti','geologici'].forEach(k=>pick(k,true));
  const geo=new Set(String(out.geologici||'').split(', ').filter(Boolean));
  Object.entries(ADJ2COMP).forEach(([a,c])=>{if(new RegExp('\\b'+a+'[aeio]\\b').test(T))geo.add(c)});
  if(geo.size)out.geologici=[...geo].join(', ');
  const interp=/(probabile|probabilmente|forse|interpretabile come|riferibile a)\s+([^.;\n–]+?)(?:\s+-\s+|\s*[.;\n–]|\s*$)/i.exec(rest);
  if(interp)out.interpretazione=interp[2].trim();
  if(out.descrizione)out.descrizione=out.descrizione[0].toUpperCase()+out.descrizione.slice(1);
  return out;
}
