/* Adatta un testo a un riquadro riducendo il corpo; restituisce righe, corpo e se è stato troncato */
function wrapText(text,maxW,size,bold,measure){
  const out=[];
  String(text).split(/\n/).forEach(par=>{let line='';
    par.split(/\s+/).filter(Boolean).forEach(w=>{
      while(measure(w,size,bold)>maxW&&w.length>1){let i=w.length-1;while(i>1&&measure(w.slice(0,i),size,bold)>maxW)i--;if(line){out.push(line);line=''}out.push(w.slice(0,i));w=w.slice(i)}
      const t=line?line+' '+w:w;if(!line||measure(t,size,bold)<=maxW)line=t;else{out.push(line);line=w}});
    out.push(line)});
  while(out.length&&out[out.length-1]==='')out.pop();
  return out;
}
function fitText(text,w,h,start,min,bold,measure){
  if(!String(text).trim())return{size:start,lines:[],trunc:false};
  for(let s=start;s>=min-0.01;s-=0.5){const lines=wrapText(text,w,s,bold,measure);if(lines.length*s*1.18<=h+0.5)return{size:s,lines,trunc:false}}
  const lines=wrapText(text,w,min,bold,measure);const n=Math.max(1,Math.floor(h/(min*1.18)));
  const cut=lines.slice(0,n);cut[cut.length-1]=cut[cut.length-1].replace(/\s*\S*$/,'')+' …';return{size:min,lines:cut,trunc:true};
}
/* Disegna la scheda con un "disegnatore" (PDF o SVG): rect, line, text, img, measure */
function drawSheet(spec,D){
  const over=[];const LBL=6,LH=7.3;
  spec.pages.forEach((items,p)=>{D.page(p);
    items.forEach(it=>{
      if(it.t==='img'){D.img(it.k,it.x0,it.y0,it.x1,it.y1);return}
      if(it.t==='text'){if(it.text)D.text(it.text,it.x,it.y,{size:it.size||6,bold:it.bold,col:it.col,align:it.align});return}
      if(it.t==='lbox'){D.text(it.l,it.lx,it.ly+5,{size:LBL,bold:true});D.rect(it.bx,it.by,it.bx+7,it.by+7);if(it.on)D.cross(it.bx,it.by,it.bx+7,it.by+7);return}
      D.rect(it.x0,it.y0,it.x1,it.y1);
      const w=it.x1-it.x0,h=it.y1-it.y0,cx=(it.x0+it.x1)/2;
      if(it.t==='usbox'){
        D.line(it.x0,it.split,it.x1,it.split);
        D.text(it.lab,cx,it.y0+(it.split-it.y0)/2+it.lsize*0.36,{size:it.lsize,bold:true,align:'center'});
        D.rect(it.x0+2,it.split+2,it.x1-2,it.y1-2,it.col,true);
        if(it.num){const f=fitText(it.num,w-8,it.y1-it.split-8,20,9,true,D.measure);
          f.lines.forEach((l,i)=>D.text(l,cx,(it.split+it.y1)/2+f.size*0.36+(i-(f.lines.length-1)/2)*f.size*1.1,{size:f.size,bold:true,align:'center'}))}
        return}
      if(it.t==='vlabel'){
        const words=it.text.split(' ');const tw=D.measure(it.text,LBL,true);
        const parts=tw>h-6&&words.length>1?[words[0],words.slice(1).join(' ')]:[it.text];
        parts.forEach((t,i)=>{const ww=D.measure(t,LBL,true);const x=cx+LBL*0.36+(i-(parts.length-1)/2)*LBL*1.25;D.text(t,x,(it.y0+it.y1)/2+ww/2,{size:LBL,bold:true,angle:90})});
        return}
      if(it.t==='check'){
        D.text(it.l,cx,it.y0+8.2,{size:LBL,bold:true,align:'center'});const bx=cx-3.5,by=it.y0+(h+8)/2-2;
        D.rect(bx,by,bx+7,by+7);if(it.on)D.cross(bx,by,bx+7,by+7);return}
      if(it.t==='opts'){
        const oh=Math.min(LH,(h-4)/Math.max(1,it.opts.length+(it.extra?1:0)));
        it.opts.forEach((o,i)=>{const y=it.y0+3+5+i*oh;D.text(o.l,it.x0+3,y,{size:LBL,bold:o.on});const bx=it.x1-8,by=y-4.6;
          D.rect(bx,by,bx+5,by+5);if(o.on)D.cross(bx,by,bx+5,by+5)});
        if(it.extra){const top=it.y0+3+it.opts.length*oh+2;const f=fitText(it.extra,w-6,it.y1-top-1,7,5,true,D.measure);
          f.lines.forEach((l,i)=>D.text(l,it.x0+3,top+f.size*0.9+i*f.size*1.18,{size:f.size,bold:true}));if(f.trunc)over.push('altri materiali')}
        return}
      /* cella con etichetta e valore */
      const labs=Array.isArray(it.l)?it.l:it.l?[it.l]:[];
      labs.forEach((l,i)=>D.text(l,it.lcenter?cx:it.x0+3,it.y0+3+5+i*LH,{size:LBL,bold:!it.lnormal,align:it.lcenter?'center':'left'}));
      if(!it.v)return;
      if(it.vinline){ /* valore accanto all'ultima riga dell'etichetta, come nel modello */
        const lx=it.x0+3+D.measure(labs[labs.length-1],LBL,!it.lnormal)+6,top=it.y0+3+(labs.length-1)*LH-0.5;
        const f=fitText(it.v,it.x1-lx-3,it.y1-top-1,8,5,true,D.measure);
        f.lines.forEach((l,i)=>D.text(l,lx,top+f.size*0.9+i*f.size*1.18,{size:f.size,bold:true}));if(f.trunc)over.push(labs[0]);return}
      const top=it.y0+(labs.length?3+labs.length*LH+1.5:3);const avail=it.y1-top-1.5;
      const f=fitText(it.v,w-6,avail,it.vsize||9,5,!!it.vbold,D.measure);
      f.lines.forEach((l,i)=>D.text(l,it.center?cx:it.x0+3,top+f.size*0.9+i*f.size*1.18,{size:f.size,bold:it.vbold,align:it.center?'center':'left'}));
      if(f.trunc)over.push(labs.join(' ')||'campo');
    });
  });
  return over;
}
